const item = $input.first().json;

function toDateOnly(value) {
  if (!value) return null;

  const date = new Date(value);

  return date.toLocaleDateString("es-CO", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    timeZone: "America/Bogota",
  });
}

function toHourMinute(value) {
  if (!value) return null;

  const date = new Date(value);

  return date.toLocaleTimeString("es-CO", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
    timeZone: "America/Bogota",
  });
}

function formatPriority(nombrePrioridad, diasSla) {
  if (!nombrePrioridad || !diasSla) {
    return "Media (3 días)";
  }

  const normalized =
    nombrePrioridad.charAt(0).toUpperCase() +
    nombrePrioridad.slice(1).toLowerCase();

  return `${normalized} (${diasSla} días)`;
}

const sharepoint = {
  Title: "PORTAL_CLIENTE",

  Id_Req: item.codigo_ticket,
  Requerimiento: item.descripcion_problema,

  Fecha_Solicitud: toDateOnly(item.fecha_creacion),
  Hora_Solicitud: toHourMinute(item.fecha_creacion),
  Fecha_Max_Respuesta: toDateOnly(item.fecha_limite),

  Nit: item.identificacion_fiscal,
  Cliente: item.nombre_cliente,


  OData__x00c1_rea_Remite: "PORTAL_CLIENTE",
  OData__x00c1_rea_Destino: item.nombre_area,


  Tipo_Requerimiento: item.tipo_requerimiento,
  Categor_x00ed_a1: item.categoria_1,
  Estado: "Abierto",
  Prioridad: formatPriority(item.nombre_prioridad, item.dias_sla),

  Recibe: item.encargado_interno,
  Reasignado: "SI",
};

/**
 * Solo agregamos Categoría 2 si viene con valor real.
 * Esto evita enviar null innecesario a SharePoint.
 */
if (item.categoria_2) {
  sharepoint.Categor_x00ed_a2 = item.categoria_2;
}

/**
 * Marcador temporal para pruebas.
 * Quitar cuando pases a producción real.
 */
sharepoint.Comentarios_adicionales = "PRUEBA CORAJE - BORRAR";

return [
  {
    json: {
      id_sync: item.id_sync,
      id_ticket: item.id_ticket,
      sharepoint,
      sharepointBody: {
        __metadata: {
          type: "SP.Data.HelpDeskBdListItem",
        },
        ...sharepoint,
      },
    },
  },
];

const item = $input.first().json;

/**
 * SharePoint REST puede devolver el ID como d.Id o d.ID.
 * Normalizamos a sp_id numérico y una bandera booleana para el IF.
 */
const rawSpId = item.d?.Id ?? item.d?.ID ?? item.Id ?? item.ID ?? null;
const spId = rawSpId === null ? null : Number(rawSpId);

return [
  {
    json: {
      ...item,
      sp_id: Number.isFinite(spId) ? spId : null,
      sharepoint_created: Number.isFinite(spId),
    },
  },
];

/**
 * Genera N "slots" de procesamiento.
 *
 * Cada slot intentará reclamar 1 ticket pendiente.
 * Si en algún slot ya no hay pendientes, el workflow termina.
 */
const maxItemsPerRun = 20;

return Array.from({ length: maxItemsPerRun }, (_, index) => ({
  json: {
    slot: index + 1,
    maxItemsPerRun,
  },
}));
